#include "economy/TradeCargoClassification.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
namespace elysium::economy {bool TradeCargoClassification::publish(CargoStackClass s){if(!s.stackStableId||!s.contentId||!s.count||stacks_.contains(s.stackStableId))return false;stacks_[s.stackStableId]=s;return true;}const CargoStackClass*TradeCargoClassification::find(std::uint64_t id)const{auto i=stacks_.find(id);return i==stacks_.end()?nullptr:&i->second;}
TradeCargoOutcome TradeCargoClassification::evaluate(const TradeCargoTransaction&t,const TradeCargoPolicy&p,const CustomsDecisionSnapshot&c,const CargoExposureCapability&cap){if(auto i=processed_.find(t.stableId);i!=processed_.end()){auto o=i->second;o.duplicate=true;return o;}TradeCargoOutcome o;if(!t.stableId||!t.stackStableId||!t.units)return o;auto i=stacks_.find(t.stackStableId);if(i==stacks_.end()||i->second.revision!=t.expectedStackRevision)return o;auto&s=i->second;if(t.units>s.count)return o;const double exposureMult=elysium::safe::finiteClamp(cap.exposureMultiplier,0.0,1.0);o.exposure=elysium::safe::nonNegative(c.baseExposure)*exposureMult;switch(s.registration){case GoodsRegistration::Registered:o.law=TradeLawResult::Lawful;break;case GoodsRegistration::LegacyUnknown:case GoodsRegistration::Unregistered:if(p.registeredMarketOnly&&!p.allowUnregistered){o.law=TradeLawResult::Rejected;return o;}o.law=c.inspection?TradeLawResult::InspectionRequired:TradeLawResult::AllowedWithMarkup;o.priceMultiplier=elysium::safe::nonNegative(p.unregisteredMarkup);o.emitStandingOutcome=c.inspection;break;case GoodsRegistration::Restricted:if(c.clearance)o.law=TradeLawResult::Lawful;else{o.law=TradeLawResult::InspectionRequired;o.emitStandingOutcome=true;}break;case GoodsRegistration::Contraband:if(c.inspection&&p.confiscateContraband&&!c.clearance){o.law=TradeLawResult::ConfiscationRequired;o.confiscatedUnits=t.units;o.emitStandingOutcome=true;}else{o.law=TradeLawResult::AllowedWithMarkup;o.priceMultiplier=elysium::safe::nonNegative(p.contrabandMarkup);o.emitStandingOutcome=o.exposure>0;}break;}before_[t.stableId]=s;s.count-=t.units;s.revision=elysium::safe::saturatingIncrement(s.revision);o.tradedUnits=t.units;o.committed=true;processed_[t.stableId]=o;return o;}
bool TradeCargoClassification::rollback(std::uint64_t id){auto b=before_.find(id);auto p=processed_.find(id);if(b==before_.end()||p==processed_.end())return false;stacks_[b->second.stackStableId]=b->second;before_.erase(b);processed_.erase(p);return true;}
} // namespace elysium::economy
